		["Out of Thunder Axe Fortress"] = "Fuera de la Fortaleza del Hacha de Trueno",
		["Scorpashi venom"] = "Veneno Scorpashi",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Los Kolkar recorren las llanuras alrededor de {area:609}; sus orejas son para {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "Los escórpidos Scorpashi cazan en las colinas alrededor de {area:2407}, en el camino al sur.",
		["The chest lies in the ruins south-west of {area:608}."] = "El cofre está en las ruinas al suroeste de {area:608}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Usa el {item:13892} de {npc:11596} en un {npc:4700} y lleva el kodo domado a su campamento, cinco veces; los Kodos envejecidos también sueltan los pellejos.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, al norte de {area:413}",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "El campamento de {npc:11596} está en el camino al sur de {area:609}, junto a {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "La torre de {npc:11863} Aldamort está en la colina al oeste de {area:599}: acepta antes su misión; el cetro que quiere está en la fortaleza.",
		["{npc:5643} and the Seer"] = "{npc:5643} Malem y el Vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} Malem se esconde en la fortaleza del Filo Ardiente, al suroeste de {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Vara de transformación de Dartol",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Sigue el camino hacia el este hasta los campamentos sátiros de {area:429}; {npc:3920} se esconde en su borde.",
		["Lightforge Ingots"] = "Lingotes Forjaluz",
		["Melyria and {npc:3901}"] = "Melyria e {npc:3901}",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Entra por el túnel en {area:419}; el tomo está en las ruinas de su extremo oeste.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Los múrlocs Branquiazul de la playa al suroeste de Menethil llevan los lingotes.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Los Ancianos enloquecidos y los Ancianos marchitos al norte del pozo de la luna llevan la {item:5475}; el cofre gastado que abre está entre ellos.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "El segundo {object:19901} está en el valle de {area:428}, de camino al oeste.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "El santuario está en la colina justo al sureste del pozo de la luna; sube por el sendero sinuoso.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}, el puesto de los elfos de la noche en el extremo este del camino: allí está {npc:3848}.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, un furbolg al que no ha tocado la corrupción, está sentado al sur del camino, bajo {area:421}.",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} lidera a los sátiros de {area:429}; él lleva la rama.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: para {npc:3961} en {area:415}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Vuelve al sur, pasado Nesingwary: las Panteras y los Raptores de Tuercespina corren por los claros al oeste del campamento, hacia la costa; los tigres mayores ocupan las colinas del suroeste.",
		["Both roam the grass around the camp and along the road north."] = "Ambos recorren la hierba alrededor del campamento y a lo largo del camino al norte.",
		["Down to {area:35}"] = "Bajada a {area:35}",
		["Druid training"] = "Entrenamiento de druida",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Sigue el camino principal al sur a lo largo de toda la selva, pasado el desvío a {object:3202}, hasta {area:35}, en el cabo sur.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Sigue la costa oeste al norte; la isla fantasma está frente a la orilla, al oeste del campamento de Nesingwary. Basta con llegar a ella.",
		["For Archmage Ansirem in {zone:1416}"] = "Para el Archimago Ansirem, en {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Desde {zone:1431} toma el camino al sur hasta la Vega de Tuercespina; las tiendas de los cazadores están justo al oeste del camino, pasado el desvío al {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un múrloc raro de la costa al oeste del campamento, suelta el {item:4614}: cógelo si te lo encuentras",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Los documentos de Herod están en una cabaña del lado oeste de la base; su caja fuerte está más al este, junto a la entrada de la cueva.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Recorre en círculo las ruinas trols del norte y del centro: cada una guarda una tablilla de piedra con las leyendas trols. Las Panteras Faucesombría merodean en sigilo por la selva que las rodea; en el campamento de Ventura y Cía. del {area:37} están los Cristales caídos.",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores y tigres mayores",
		["River Crocolisks swim the river by the {area:99}."] = "Los Crocoliscos fluviales nadan en el río junto al {area:99}.",
		["River crocolisks"] = "Crocoliscos fluviales",
		["Skullsplitter trolls"] = "Trols Machacacráneos",
		["Snapjaw Crocolisks"] = "Crocoliscos Quijaforte",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "Los Crocoliscos Quijaforte toman el sol en la orilla y en las islas de la costa al norte de {area:35}.",
		["Stranglethorn Tigers"] = "Tigres de Tuercespina",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Toma el camino al norte; {npc:738} lo patrulla y el campamento está en las colinas del oeste.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Los rebeldes de Kurzen ocupan el campamento al este del {area:99}; recorre su borde exterior, donde están los Jíbaros y los Auxiliadores, y saquea las cajas de suministros junto a las tiendas.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Los trols Machacacráneos ocupan las ruinas al este del camino entre Nesingwary y {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Los tigres adultos merodean por las colinas justo al sur y al oeste del campamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Los tigres mayores vienen después, a la vuelta del {area:99}",
		["The haunted island"] = "La isla fantasma",
		["The jungle ruins"] = "Las ruinas de la selva",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "El mineral lo sueltan los kóbolds Mostacho Seco de {zone:1417}",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "Thorsen patrulla el camino al norte del campamento, hacia el {area:99}.",
		["Young tigers and panthers"] = "Tigres y panteras jóvenes",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de una caja de {object:263}",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:469}, in the hut"] = "{npc:469}, en la cabaña",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, desde {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} colecciona {item:2755}: casi todos los humanoides de la selva sueltan las páginas. Convierte las páginas en capítulos sobre la marcha.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} y los raptores colazote",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, el gran tigre, tiene su guarida en la cima de la colina al suroeste del campamento; los Raptores colazote corren al sur de ella, de camino a {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, en la taberna",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773}, en {area:35}",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: basta con echar un vistazo por el campamento de los cazadores",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Un {npc:2434} acecha sin ser visto en las afueras de {area:271}; mátalo y lee el contrato que lleva.",
		["Crushridge ogres"] = "Ogros Aplastacresta",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Al este por el camino hasta {area:76}. Los {npc:256028} sueltan los cristales; Noboru recorre las ruinas y suelta su garrote.",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Sigue el camino al este desde {area:287}, por {area:1057}, hasta {area:320}.",
		["Follow the road north to the draenei of the {area:657}."] = "Sigue el camino al norte hasta los draenei de {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} en {zone:1453}: guárdalo",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} en {area:35}: guárdalo",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} en {area:35}: guárdalo",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} en {area:271}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Ve al norte pasando {area:314}; los fragmentos brillan en la colina junto a {area:333}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Solo si Gluggle te dio el colgante en Vega de Tuercespina",
		["Phizzlethorpe"] = "Fiseltor",
		["South-east along the loch to the dig site."] = "Al sureste por el lago hasta la excavación.",
		["Subdue the succubus"] = "Somete a la súcubo",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Los ogros Aplastacresta ocupan las colinas al norte de {area:280}. Más al norte, un cofre de madera gastado contiene el {item:3706}; {npc:2320}, de {quest:537}, está justo a su lado.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Los trols Secacorteza viven en las colinas al sur de {area:314}; los médicos brujos están en el poblado y los cazadores de las Sombras guardan el fondo del valle.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "El mensajero recorre el camino al oeste de {area:314} con dos guardias; atráelos fuera del camino.",
		["The shards lie at the far end of {area:318}."] = "Los fragmentos están en el extremo de {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Los dos naufragios están en la bahía al oeste de la cala. Las cartas de navegación y los diarios están dentro; las gemas están en el fondo del mar a su alrededor. Los nagas Espinadaga nadan por toda la bahía.",
		["The western swamp"] = "El oeste de la ciénaga",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Al oeste por la costa hasta la cala de los goblins; Lolo vigila desde las rocas de encima.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jóvenes, Girapenas y Jaguares del pantano recorren la ciénaga alrededor del camino.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} para la capa de {npc:2438}, de {npc:2381}, si no tienes",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Aplastacresta",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, camino de {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, en la catedral",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la biblioteca real del castillo",
		["{npc:185335}, at the same circle"] = "{npc:185335}, en el mismo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: tres bichos que atrapar en Tierras Altas de Arathi, {zone:1443} y Vega de Tuercespina",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: atrápalo, para {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} y {npc:2713}",
		["{npc:2713}'s errand"] = "El encargo de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, un ogro mago, ocupa la cueva del extremo sur del valle Secacorteza.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está enjaulado en el extremo norte del santuario. Libéralo y mantenlo con vida mientras salís; después, su cofre te espera junto al camino.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula el íncubo a ti",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}. Usa el {item:6913} en el círculo de invocación de allí y derrota a la súcubo que aparece. Si aceptaste {quest:65602}, entrégale también la {item:190309}, colócala en el mismo círculo y derrota al íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si la aceptaste",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Vuela a Theramore",
		["Follow the road north to {area:608}."] = "Sigue el camino hacia el norte hasta {area:608}.",
		["Follow the road south to {area:2407}."] = "Sigue el camino hacia el sur hasta {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Sigue el camino hacia el oeste por el norte de {zone:1443} hasta las ruinas de {area:2405}. La torre de {npc:11863} está en la colina de allí, de camino al naufragio.",
		["Maraudine centaurs"] = "Centauros Maraudine",
		["Rock Elementals"] = "Elementales de piedra",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "El siguiente encargo del Prospector Ryedol es en {area:1517}: omítelo.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Los centauros Maraudine ocupan {area:607}, al oeste del cementerio; todos sueltan los tótems.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Los elementales de piedra ({npc:92}) recorren el sureste de {npc:2921}; las águilas ratoneras gigantes ({npc:2831}) y los coyotes del risco mayores ({npc:2729}) comparten la llanura al oeste.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Los enanos Forjatiniebla acampan justo al norte de la excavación; el Mapa arrugado está entre sus tiendas. Los Tuneladores y los Tejeoscuros llevan el Pico de la suerte de Ryedol. Los Coyotes del risco recorren las laderas de alrededor.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Las almejas están en la costa noroeste de la Vega de Tuercespina, en la siguiente guía: guárdala",
		["The excavation crate"] = "El cajón de la excavación",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "El cofre del barco naufragado está en la orilla, justo al oeste de la torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Los Devastadores no-muertos recorren los campos de huesos al sur del Poblado Magram, al este del aquelarre; en el extremo sureste, usa el {item:15848} para atraer a los Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolta a {npc:12277} de vuelta hacia el cementerio",
		["for the Dustwallow loop in the next guide"] = "para la vuelta por Marjal Revolcafango de la siguiente guía",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} en {zone:1455}: guárdala",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} en {area:271}: guárdala",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} en {zone:1455}: guárdala",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "solo si llevas {item:2868} (los fabrica un herrero)",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, un jefe centauro, acampa en la costa noroeste, al norte de la torre de {npc:11863} Aldamort.",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: atrápalo, para My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, junto a {npc:2921} Veriatus",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "La siguiente prueba de {npc:2921} Veriatus requiere equipo fabricado: omítela.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} está al borde de {area:596}, al suroeste de {area:2407}; {object:176751} están entre los esqueletos. Un {npc:217590} se arrastra por el cementerio: atrapa uno con el Entomology Starter Kit y márcalo.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Ignatz el \"Apestoso\"",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:4772} enseña a los enanos en la {area:803}, al este de {area:131}, en el camino a {zone:1432}, junto a los carneros de {npc:1261}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender equitación, y al aprenderla recibes una montura. {npc:7954} enseña a los gnomos en el {area:189}, justo al este de {area:131}, junto a los mecazancudos de {npc:7955}. Puede que Forever permita a cualquier raza aprender con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40, muestra todos los colores.",
		["Bloodsail camp"] = "Campamento Velasangre",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Cold Eye Basilisks"] = "Basiliscos Ojogélido",
		["Defeat the challengers and {npc:6238}"] = "Derrota a los aspirantes y a {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todos los Velasangre sueltan Barril de tabaco y uno de ellos lleva el ojo de {npc:2493}; los Aventureros recorren la orilla justo al norte del pueblo. Las cartas de navegación y las órdenes están en el campamento pirata de la {area:43}, al sur de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Cualquier seguidor de Zanzil puede soltar el mejunje; {npc:2537} recorre el sur del campamento.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Sigue el camino al este de vuelta a Theramore. Tervosh, Lady Jaina y los oficiales están en la torre y en la {area:514}.",
		["Gorilla hills"] = "Colinas de los gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entrega los colmillos y quédate: llegan tres oleadas de gorilas, la última con {npc:1514}. Lucha con la salud al máximo.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Sal del pueblo por el túnel y sigue la costa al norte; la carta está en el campamento Velasangre de la playa, por donde camina \"El Guapo\" Duncan.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "La siguiente tarea de MacKinley te manda a por ogros élite: omítela.",
		["Mirefin murlocs"] = "Múrlocs Ancalodo",
		["Naga Explorers"] = "Expedicionarios Naga",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "De camino al norte hacia {area:392}, la {area:720} está frente a {area:391}, al sur del pueblo: cruza vadeando los bajíos del banco de arena. {npc:6236} te envía cuatro aspirantes y luego a {npc:6238} (nivel 33), de uno en uno.",
		["Paladin: {quest:1661}"] = "Paladín: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Vuelve a bajar al pueblo; Trémulo está en la entrada del túnel.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Ve al este; los Horrores enredados del camino también sueltan los ensayos. Busca en la orilla de la {area:74}, donde las ruinas del templo asoman del agua.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Ve tierra adentro hasta las colinas de los gorilas del Valle del Velo de Bruma. Los Gorilas del Valle Velo de Bruma viejos sueltan las tripas; {npc:1449} está sentado entre ellos.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Ve al norte hasta las colinas al oeste del camino. {npc:2535} y {npc:2536} están juntos justo al norte del poblado de Zanzil.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Ve al noreste, pasado el campamento de Nesingwary, y sigue el camino al norte hasta el campamento en lo alto de la vega. Por el camino, una {npc:217588} se arrastra por la selva al sureste del campamento de Nesingwary: atrapa una con el Kit de iniciación a la entomología y márcala.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Ve al noroeste desde la mina hasta la bahía de la costa noroeste. Las Almejas gigantes están en el fondo y guardan las perlas; {npc:2624} nada entre ellas y suelta la {item:4034}.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Ve al sur hasta la cabaña del gigante, en mitad del pantano.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "El siguiente encargo de Cuernomarino te lleva de vuelta a las Tierras Altas de Arathi: omítelo.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Apestoso espera al oeste de la mansión, en el pantano bajo la {area:504}. Llévalo hasta sus hojas de cienagrana y mantén alejadas de él a las criaturas del pantano.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Toma el camino al norte hasta la mansión en ruinas; Jarl vive en la choza de al lado y la tierra suelta está en la esquina de la casa.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "Toma el {area:2257} desde el {object:28027}. {npc:5637} está en la sala de los Reclaimers junto a {object:32356}, {npc:1356} en la propia sala y {npc:2786} en {object:32383}. La siguiente guía continúa en vuelo hasta {area:144}.",
		["The Bloodsail captains"] = "Los capitanes Velasangre",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Los Basiliscos Ojogélido descansan en las rocas al oeste de la mina.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Los múrlocs Ancalodo abarrotan la costa norte pasada la {area:497}; termina las lenguas con las tortugas que hay a su lado.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Los capitanes están en los barcos fondeados frente a la {area:43}, cada uno con una tripulación de piratas de nivel 42-45: Aguasmansas (45) y Sinquilla (46) en las cubiertas más cercanas, y {npc:2546} (48) en el buque insignia. A nivel 42 es una pelea para un grupo o para el final de la guía; si vas, limpia antes cada cubierta. El pergamino de Cortello está en el naufragio junto a la orilla.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Los desertores acampan al sur del camino, al oeste de la cabaña de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "La madera a la deriva llega a la orilla oriental.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Los naga recorren las playas al norte del campamento Velasangre; sueltan los juncos.",
		["The north-west coast"] = "La costa noroeste",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "El siguiente pergamino del enigma está en el oeste del Marjal Revolcafango: omítelo.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "El pergamino está en el pantano al norte de Biggs. Los Caminalodos al norte de él pueden soltar los ensayos de Khadgar.",
		["The sunken temple"] = "El Templo Sumergido",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "El ritual de Unbagwa",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Zanzil's village"] = "El poblado de Zanzil",
		["for {area:1438}: keep it"] = "para el {area:1438}: guárdalo",
		["for {npc:2616} in Theramore: keep it"] = "para {npc:2616}, en Theramore: guárdalo",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635}, en {area:348}: guárdalo",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770}, en el {area:99}, en la vuelta por el norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "solo si llevas una {item:3853} (la fabrica un herrero)",
		["with the spices from Theramore"] = "con las especias de Theramore",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cocina en {object:2169}; {npc:5384} está en el {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: otros colores, 20 o",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, el Archivo Real en {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: atrápala, para {quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}, último piso",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "El siguiente encargo de {npc:2498} sobre Zanzil empieza en {zone:1441}: omítelo.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} y {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada frente a la costa noroeste, en la vuelta por el norte",
		["{npc:384}: other colours, 20g"] = "{npc:384}: otros colores, 20 o",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, en {object:2164}: {npc:6251}, en {area:392}, la recoge al final de la siguiente guía",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: otros colores, 20 o",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: para el {area:1438}; guárdalo",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, en la Catedral de la Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} ofrece después El Cazavientos (1791): la cadena del arma torbellino, con un élite al final, está en la guía de clase de guerrero Arma torbellino.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864}, en {zone:1446}; guárdalo",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: otros colores, 20 o",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Perlas azules de la Vega de Tuercespina",
		["Raleigh's next errand is in the {area:796}: skip it."] = "El siguiente encargo de Raleigh el Devoto es en {area:796}: omítelo.",
		["Ride back east to {area:1898}."] = "Vuelve al este hasta {area:1898}.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "Cabalga al norte hasta {area:144} y vuela a {area:271}. {npc:3980} predica junto a la posada.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Las Crías hirvientes anidan en el barranco al este de {npc:2888}; deja en paz a los Guardianes abrasados (élite). El {item:4612} cae muy pocas veces: cógelo si sale mientras subes de nivel.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Las dos primeras jaulas están juntas en el poblado Secacorteza al sur de {npc:5634}; la tercera, en el siguiente poblado al este. Cualquier trol Secacorteza puede soltar un collar.",
		["Theramore"] = "Theramore",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Witherbark villages"] = "Poblados Secacorteza",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} está en los muelles donde atraca el barco.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La siguiente misión de {npc:2817} no da experiencia: omítela.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La siguiente tarea de {npc:2888} es una caza élite: omítela.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa en el camino al este de {area:348}.",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} sigue pagando por los collares: entrega los que te sobren",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Vuelve a las {area:1117}. Cualquier naga Crestafuria de allí puede soltar escamas.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "Toma el barco a {area:1108} y cabalga hacia el este hasta {area:1105}. Las misiones de {npc:14637} en la costa requieren nivel 45.",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Dominios Tótem Siniestro",
		["Grimtotem tauren"] = "Tauren Tótem Siniestro",
		["Grind to 45"] = "Farmea hasta el 45",
		["Hatecrest naga"] = "Nagas Crestafuria",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Vuelve a {area:1108}; el goblin está junto al muelle.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Vuelve al oeste por el camino y luego al norte hasta las colinas de los Dominios de los Cicatriz de Rabia. Cualquier yeti de aquí puede soltar un pellejo; alguno puede soltar un {quest:7735}, que {npc:7852} McGrubben también paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cabalga hacia el este hasta la Avanzada Gordunni, en las colinas al sureste del valle de los yetis: Brujos y Chamanes Gordunni ocupan el campamento y los Toscos Gordunni deambulan por las laderas de alrededor y más al norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cabalga hacia el norte hasta el valle de los yetis. Cualquier yeti Cicatriz Feral puede soltar un pellejo grueso; {npc:5346} (nivel 48) merodea por el centro.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cabalga hacia el noreste hasta el puesto de los elfos de la noche en la frontera de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cabalga hacia el sureste hasta los gnolls Zarpaleña; las mochilas del mensajero están en su campamento del sur, y un paquete que hay dentro inicia una entrega a {area:489}. La colmena Zukk'ash está justo al sur: abre paso hasta la vaina que retiene a Raschal el Mensajero, libéralo y mantenlo con vida al salir.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Zancacostas, Zancaprofundas y Asaltaolas (gigantes élite) vadean la costa al norte del muelle: dispara a uno con {item:18904} y mata al gigante encogido. Elementales marinos y Rocíos del mar flotan entre las mismas olas.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Toma el barco a {area:1108} y sigue la orilla hacia el sur hasta el bote de remos destrozado en la playa.",
		["The courier's boat"] = "El bote del mensajero",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Camina hacia el sur por la isla hasta las ruinas naga; el cenador está entre ellas.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "Terminas en el muelle de {area:1108}: la guía de {zone:1446} empieza con el viaje hacia el este desde aquí.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande en {zone:1457}: la ruta te lleva allí a nivel 47",
		["{item:11463}, from the backpacks"] = "{item:11463}, de las mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "Las recargas de {npc:14637} son de nivel 55: omítelas.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "Después {npc:3936} te pide que lleves noticias a {zone:1457}: omítelo, {area:976} te enviará allí en su lugar.",
		["{npc:3936}, beside him"] = "{npc:3936}, a su lado",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: su respuesta espera en {area:702}, más adelante",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, en lo alto del bastión",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} espera hasta el final del recorrido por el continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Gives the {item:8585}"] = "Da el {item:8585}",
		["He runs off to keep Rizzle busy"] = "Sale corriendo para entretener a Rizzle",
		["Pool by {area:979}"] = "Charca de {area:979}",
		["Ride back west to {area:976}."] = "Vuelve al oeste hasta {area:976}.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cabalga hacia el este por las dunas hasta el puerto goblin de la costa noreste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cabalga hacia el noroeste hasta el campamento de los trols Furiarena en {area:979}. Usa el {item:8584} en el borde de su charca; los trols están cerca, así que atrae primero a los más próximos.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cabalga hacia el sur hasta el campamento de excavación del {area:1938}. {npc:7771} te da un yelmo detector: póntelo para ver los montículos de {quest:3161}, abundantes en la arena alrededor del campamento y hacia el suroeste, hacia los ogros.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cabalga hacia el suroeste hasta la Base Machacaduna. Está llena de Toscos y Déspotas Machacaduna (46-48); {npc:12046} (49) está en el centro rodeado de guardias: acaba primero con ellos.",
		["The Wanted poster beside him"] = "El cartel de Se busca a su lado",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La tortuguita {npc:5955} se esconde en el extremo norte del valle. Llévala a casa con su pareja {npc:6015}, junto al agua justo al este de {area:977}: camina despacio y las bestias del desierto van a por ella, así que mantenla con vida.",
		["The pool by {area:979}"] = "La charca de {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "El mismo cartel: {npc:7847} llega mucho más tarde, después de {area:976}",
		["The {area:1938}"] = "El {area:1938}",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: la ruta te lleva allí a nivel 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, en el lado este del pueblo",
		["{npc:5955}'s escort"] = "La escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto a la torre de agua",
		["{npc:7408}, next to him"] = "{npc:7408}, a su lado",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: su caja va a {area:702}, más adelante",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "La siguiente entrega de {npc:7881} vuelve a {area:35}: omítela.",
		["{quest:2864}, north side of town"] = "{quest:2864}, en el lado norte del pueblo",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ride back north to Ironband's camp."] = "Vuelve al norte hasta la Excavación de Vetaferro.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Cabalga hacia el este por la orilla sur del lago hasta la Excavación de Vetaferro.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Sigue primero por el camino hacia el este hasta el bastión: la {item:6091} caduca una hora después de {area:42}, y las bestias de los magos de sangre llevan más tiempo.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Cruza el portal hasta {zone:1457}. El Templo de la Luna está en el sur de la ciudad.",
		["Temple of the Moon"] = "Templo de la Luna",
		["The bloodmages"] = "Los magos de sangre",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "La segunda ronda de los magos de sangre paga las mismas partes con un objeto de mejora y sin experiencia: omítela.",
		["The {area:1517} dig"] = "La excavación de {area:1517}",
		["for {quest:2990} at {area:1438}, later"] = "para {quest:2990} en {area:1438}, más adelante",
		["the book on her table"] = "el libro de su mesa",
		["the soil comes from {zone:1449}, later"] = "la tierra viene de {zone:1449}, más adelante",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, en lo alto del árbol",
		["{npc:7740}, beside her"] = "{npc:7740}, a su lado",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "El siguiente encargo de {npc:7907} va a {zone:1446}: omítelo.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guárdala, las plumas llegan al final de la guía de {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "La siguiente tarea de {npc:8022}, {item:9471}, es una misión de {area:978}: omítela.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, en lo alto del bastión",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "Kalaran Espada del Viento está en el borde de La Caldera, al sur de {area:1446}. Escucha su historia.",
		["The Grimesilt outhouse"] = "La letrina de Limugre",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "El elfo de la noche está solo al oeste de {area:1446}. Escucha su historia.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La siguiente tarea del prisionero, El libro de contabilidad de {zone:1446}, te envía a {zone:1435} y {zone:1445}: omítela.",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre en el norte de La Caldera. Los planos secretos están en su cornisa superior; los Incendosaurios nadan en las charcas de lava más adentro, así que atráelos hasta el borde. Mantente lejos de {npc:14621} y sus guardias élite del fondo.",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus está junto al rey Magni en {object:171709}.",
		["Bind and train"] = "Vincula y entrena",
		["Bones and equipment"] = "Huesos y equipo",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Los huesos de dinosaurio ({item:11114}) están en el suelo del suroeste, entre los estegodones: son élite, así que recoge los huesos a su alrededor y consigue el resto de los diemetradones. El {item:11112} de la expedición está en la jungla del suroeste.",
		["Eastern Pylon"] = "La Torre del Este",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775} en {zone:1444}: guárdala",
		["Four rune rubbings in {zone:1447}: keep it"] = "Cuatro calcos de runas en {zone:1447}: guárdala",
		["Lar'korwi Mates and the raft"] = "Amigos de Lar'korwi ({npc:9683}) y la balsa",
		["Northern Pylon"] = "La Torre del Norte",
		["Ride north along the western jungle back to the refuge."] = "Cabalga al norte por la jungla del oeste de vuelta al refugio.",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Cabalga al norte hasta {area:1943}, donde el robot está entre los gorilas. No entres en la cueva profunda de allí.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Cabalga al sur por el lado este. Los diemetradones jóvenes ({npc:9162}) pastan en la jungla del este y los {npc:9165} vuelan cerca de los acantilados del este; ambos sueltan las escamas de {npc:9998}.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Cabalga al sur hasta {area:537}, en el centro del cráter, y luego al este hacia la jungla del este. Hay grupos de cristales por todo el cráter, muchos alrededor de {area:537}: coge unos cuantos de más de cada color. Los latigadores pétalo de sangre ({npc:6509}) y los trilladores sueltan los pétalos; el {item:11113} de la expedición está en un campamento abandonado de la jungla del este.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Los amigos de Lar'korwi ({npc:9683}) merodean por la jungla al oeste de {npc:9619}. La balsa naufragada está en la orilla del lago; el pequeño fardo está en el agua a su lado. Guarda la brújula, el mapa y la llave para {npc:8737}. Cualquier bestia del cráter puede soltar {item:11116}: haz clic derecho en él.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "El trillanodonte muerto yace junto al agua, al norte de {npc:9619}.",
		["The pylon stands on the eastern cliffs."] = "La torre está en los acantilados del este.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "La torre está en los acantilados del oeste. Los {npc:9167} vuelan por todo el lado oeste.",
		["The relics are in the {zone:1428}: keep it"] = "Las reliquias están en {zone:1428}: guárdala",
		["Western Pylon"] = "La Torre del Oeste",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera en {object:32359}.",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc en {zone:1447}, guárdala",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: los mocos están en {zone:1448}, guárdala",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} está justo fuera del refugio.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, en la entrada del refugio",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Sube a la cima de {area:249} y planta la cabeza en el montículo de tierra blanda.",
		["Druid training"] = "Entrenamiento de druida",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina con {quest:4808} en {area:2255}, {zone:1452}: guárdala",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Sigue el camino al oeste y luego sube al norte hasta el campamento goblin en {area:251}.",
		["Mosshoof Coursers"] = "Maledictores Pezuñamusgo ({npc:8761})",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Opcional: {npc:8395} quiere dos plumas de hipogrifo sin estropear ({item:10450}) de los hipogrifos alrededor de su campamento. Los datos no indican experiencia para ella.",
		["Ride back east along the road to the Vigil."] = "Vuelve al este por el camino hasta la Vigilia.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Cabalga al noreste desde el santuario: {npc:8405} acampa en {area:1224}, en las colinas sobre el camino.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Los ogros Pirontraña ocupan la gran roca al norte de la Vigilia, con los toscos en su lado este.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Los fantasmas altonatos rondan las ruinas alrededor del santuario; los sátiros Haldarr ocupan el campamento justo al norte.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Las nagas Látigo de Ira de las {area:1221} llevan {item:13815}. Las cuatro runas de {npc:8507} están entre las ruinas: usa su {item:10445} en cada una.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Los maledictores Pezuñamusgo ({npc:8761}) más cercanos pastan en las colinas al noreste de {area:1224}, hacia {area:1219}; una manada mayor recorre el terreno abierto del sur.",
		["The wildkin are in {zone:1452}: keep it"] = "Los lechúcicos están en {zone:1452}: guárdala",
		["The {area:1221}"] = "Las {area:1221}",
		["Wildkin feathers"] = "Plumas de lechúcico",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: los {npc:7864}, un 10 % aprox.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} acampa en {area:1219}, en el norte; su equipo está repartido por todo el {area:1220}, justo al sureste de él.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: los orcos Roca Negra sueltan los medallones, mantenla abierta por todas las Estepas",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455} no tiene instructor de druidas: toma el portal para subir a {zone:1457} y entrena en el {area:1658}; luego vuelve a bajar a {area:702}.",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "Termina en {zone:1413}: guárdala",
		["First crater"] = "Primer cráter",
		["Five feathers buy a little Timbermaw reputation"] = "Cinco plumas dan un poco de reputación con los Fauces de Madera",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Sigue el camino al norte hasta la entrada de la cueva de {area:1769}; {npc:15395} la vigila.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Sigue el camino al norte hasta el valle de cráteres y ve a cada cráter, matando las bestias entrópicas y los horrores entre ellos.",
		["Keep her alive until she is out of the cave"] = "Mantenla con vida hasta que salga de la cueva",
		["Oozes"] = "Mocos",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa está en la salida de {zone:1452} del túnel: guárdala",
		["Second crater"] = "Segundo cráter",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "Entra en la cueva: {npc:11558} y {npc:11557} están justo dentro.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "Los mocos malditos y corruptos se deslizan por los arroyos y charcas viles alrededor de {area:1763} y {area:1765}: mátalos y usa las jarras de moco vacías de Laris en sus restos.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Los fúrbolgs Muertobosque viven en el poblado justo al suroeste de {npc:11554}; guarda las plumas de penacho Muertobosque que sueltan.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Los antárboles Combadera de {area:1767}, al este de {area:2618}, llevan el {item:11503}.",
		["The {area:2479}"] = "El {area:2479}",
		["Third crater"] = "Tercer cráter",
		["{area:1763} again"] = "{area:1763} otra vez",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763} es el templo en ruinas al norte del claro. Algunos de sus cultores sueltan una {item:13140}, más o menos una de cada treinta muertes: abre la celda de {npc:11018} en {area:1770}, la cueva del fondo. Si cae, despeja la salida antes de liberarla; si no, sáltate sus misiones.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} es el valle de sátiros del noroeste, con {npc:10648} al fondo. Él suelta la {quest:939}; cualquier sátiro Fuego de Jade puede soltar {item:11674}.",
		["{item:13140}, a rare drop"] = "{item:13140}, botín poco común",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, en las ruinas justo al este de {npc:11554}",
		["{quest:8470}, a rare drop"] = "{quest:8470}, botín poco común",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Follow the road east across the zone to the chapel."] = "Sigue el camino al este cruzando la zona hasta la capilla.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Sigue el camino al oeste hasta el campamento de {npc:9298}, junto a las aguas termales.",
		["For Kernda in {area:1769}: keep it"] = "Para Kernda en {area:1769}: guárdalo",
		["Free Darrowshire Spirits: talk to them"] = "Libera espíritus de Villa Darrow ({npc:11064}): habla con ellos",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Los yetis Cardo Nevado viven en las colinas al sur de {area:2244}, y las Quimeras venfresco en el valle hacia {area:2255}.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Guárdalo: Gregan, en {zone:1444}, prepara el elixir más adelante",
		["On {npc:10978}, by the inn"] = "Sobre {npc:10978}, junto a la posada",
		["Optional: {area:1417}"] = "Opcional: {area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Recoge los suministros alrededor del carro y recupera el amuleto de {npc:10301} de las lechubestias cercanas.",
		["Ride north-west back to the village."] = "Cabalga al noroeste de vuelta al pueblo.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Cabalga al sureste valle abajo hasta la caja dañada de {npc:10301}, en la nieve de {area:2245}, con su carro destrozado justo al este.",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "¿No llegas al nivel 54 después de los yetis? Hacer {area:1417} (50-54) en grupo en vez de matar enemigos te lleva allí más rápido. Después vuelve a {area:2255}.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "El caldero Muertobosque de {zone:1448}: guárdalo",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "La Plaga alrededor de {area:2264}, al oeste de la capilla, suelta ambos tipos de Piedra de la Plaga; de ellos surgen espíritus de Villa Darrow ({npc:11064}): habla con cada uno para liberarlo.",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "El poblado de los fúrbolgs Nevada está al este de {area:2255}: chamanes (56-57), vigilantes del cubil (55-56) y ursas (57-58), todos por encima de ti. Mata primero a los chamanes, que curan, y atrae desde el borde. {npc:10738}, en la cueva del fondo, es élite: no entres.",
		["The next guide starts here and flies to {area:3197}."] = "La siguiente guía empieza aquí y vuela a {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Las ruinas rodean el lago helado al sur de {area:2253}. Recoge los cuatro fragmentos de reliquia que hay en las ruinas y las Plumas Lunadón del suelo, donde merodean los lechúcicos.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Las tres piezas de la muñeca están en las casas en ruinas de {area:2262}; al recoger una pueden aparecer fantasmas. Combínalas para formar la muñeca.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "El campamento Nevada del oeste está en las colinas entre {npc:11556} y {npc:9298}. Cualquier fúrbolg de aquí puede soltar un {item:12771} (más o menos uno de cada diez) y, rara vez, un {quest:8471}: haz clic derecho en el que caiga. Guarda el {quest:6031} que sueltan los fúrbolgs para Meilosh.",
		["{item:12771}, a rare drop"] = "{item:12771}, botín poco frecuente",
		["{npc:10301}'s camp"] = "El campamento de {npc:10301}",
		["{npc:10301}'s supplies"] = "Los suministros de {npc:10301}",
		["{npc:10926}'s doll"] = "La muñeca de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} y {npc:10977} vienen después",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556} guarda la entrada de {area:1769}, al noroeste de {npc:9298}.",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, para Meilosh más adelante",
		["{quest:8471}, a rare drop"] = "{quest:8471}, botín poco frecuente",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
