		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Empieza en {zone:1446}, al sur de {zone:1445}. La última zona de esta guía completa el mapa de {zone:1414}. Aquí hay 20 zonas por descubrir, niveles 40-50.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "La otra salida del túnel de {area:1769} lleva a {zone:1452}. {area:2255} es un pueblo goblin neutral con maestros de vuelo de ambas facciones.",
		["any one of these names counts"] = "cualquiera de estos nombres cuenta",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} está al sur de {zone:1445} y {zone:1441}. {area:976} es un pueblo goblin neutral.",
		["{zone:1448} is north of {zone:1440}."] = "{zone:1448} está al norte de {zone:1440}.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "Se llega a {zone:2482} desde {zone:1452} por {area:2256}, en el sur. Es la zona de subida de nivel de final de juego de Forever.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Exploración: {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Los cielonatos empiezan aquí. Los demás toman un barco celeste, que sale cada cinco minutos más o menos; cualquier facción puede tomar cualquiera de los dos.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "El barco celeste sale de los acantilados al sur de {area:17045}, al norte de {zone:1456} (otro sale de {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "El barco celeste sale del lado norte de {area:279}, en {zone:1416} (otro sale del norte de {zone:1456}).",
		["any one of these names counts"] = "cuenta cualquiera de estos nombres",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "Vuelve por la playa, pasando el campamento pirata: la caja de botas y la caja frágil con la lente están en su extremo sur.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "Vuelve al campamento Crines de Acero. Los geomantes y los defensores ocupan su mitad este; {npc:3438} camina entre ellos.",
		["Back west along the road."] = "Vuelve al oeste por el camino.",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "Ve al este, a {area:1703}; {npc:9316} está en el campamento justo al sur.",
		["East to {area:392}, on the coast."] = "Ve al este, a {area:392}, en la costa.",
		["Follow the road east to the outpost above the {area:814}."] = "Sigue el camino al este hasta el puesto sobre {area:814}.",
		["Follow the road south-east to {area:392} on the coast."] = "Sigue el camino al sureste hasta {area:392}, en la costa.",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "Los Quijafortes del oasis se arrastran por {area:387}, al suroeste de {area:380}, y por {area:388}.",
		["Razormane camp"] = "Campamento Crines de Acero",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "Ve al sur, al puesto de vigilancia de {npc:3389} en la frontera Kolkar.",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "Al sureste de {area:380}. Prueba las semillas en la fisura burbujeante de la orilla este del oasis.",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "Los Merodeadores de la savana cazan en las llanuras entre el pueblo y el campamento Crines de Acero, al este. En el campamento, los buscadores de agua y los tejespinas ocupan la mitad oeste y los cazadores el centro; las cajas de suministros están en el extremo este.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "Las pozas están justo al norte de {npc:3389}. Entra en el agua para explorarlas; los Champiñones cargados para Helbrim crecen a su alrededor. Mata a todo Kolkar que encuentres para conseguir brazales.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "Los cubos de herramientas con las babosas están alrededor de la perforadora de Ventura y Cía. en {area:382}, al este de {npc:9316}.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "Los Truenagartos y los Lomorrayos pastan justo al otro lado del puente, bajo {area:379}.",
		["Thunder lizards across the river"] = "Truenagartos al otro lado del río",
		["Zhevra"] = "Astacebras",
		["Zhevra Runners graze north and east of town."] = "Los Galopadores astacebra pastan al norte y al este del pueblo.",
		["{area:1898} cultists"] = "Fanáticos de {area:1898}",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380} es tu base en esta guía. Todos los que necesitas están a pocos pasos de la posada.",
		["{npc:3442} in {area:392}: later, on the way"] = "{npc:3442} en {area:392}: más tarde, de camino",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: la consola está en {area:382}, más tarde",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: las arpías vienen más tarde, en {area:383}",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} acampa junto al camino que va al este, hacia {area:392}.",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878} acampa junto al camino de {area:380} a {area:392}. {object:58369} está en el sur del campamento Crines de Acero, justo al norte de él.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} hace {item:6636} con el alquitrán y la bolsa. Úsalo junto al brasero a su lado para revelar a {npc:5893}, mátalo para conseguir {item:6655} y luego pon la ascua en el brasero.",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900} espera en la orilla al sur de {area:379}, al otro lado del puente.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} está en la loma al norte del campamento Crines de Acero.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, tu {item:5176} y {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, en el muelle",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}: {area:228} en {zone:1421}, en la próxima guía",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["At the {area:2362}"] = "En el {area:2362}",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "Vuela a {area:1638}: {npc:3033} te entrena en {area:1639}. Cielonato: después vuelve volando a {zone:1454} para el zepelín.",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "Sigue la orilla del lago al sureste y nada hasta {area:172}. Los gnolls Putrepellejo cubren la isla; todos sueltan icor. No entres en {area:235}, en el lado norte, salvo que vayas a por el nicho opcional: los gnolls de allí son de nivel 18-22.",
		["Follow the lake shore south-east toward {area:172}: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Sigue la orilla del lago hacia el sureste, hacia {area:172}: los Machacadores y Cazamareas Anca Vil de allí sueltan los ojos de múrloc.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Sigue el camino al noreste hasta la casa de los Yorick, en {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Sigue el camino al sur. {object:1627} está junto a él, al norte de la Aldea Piroleña.",
		["Keep it: Thork at the {area:380}"] = "Guárdala: Thork, en {area:380}",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "Guárdala: {npc:2216}, en {area:272}, en una guía posterior",
		["Mottled Worgs"] = "Lupos jaspeados",
		["Mottled Worgs prowl the hills around the house."] = "Los Lupos jaspeados merodean por las colinas alrededor de la casa.",
		["North again to the Yoricks' house."] = "De nuevo al norte, a la casa de los Yorick.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Al norte de {area:228}. {npc:1983} ronda {area:240}: mátalo y luego cruza el campo.",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "Al sureste por el camino hasta {area:233}. Los Protectores Dalaran vigilan las afueras y los Magos Dalaran el pueblo; ambos sueltan colgantes. Los Zahoríes y Vigilantes Dalaran patrullan los caminos de alrededor. No te metas en el centro, donde está {npc:2120}.",
		["Speak with {npc:10540}, in Grommash Hold"] = "Habla con {npc:10540}, en el Fuerte Grommash",
		["Speak with {npc:3230}, in Grommash Hold"] = "Habla con {npc:3230}, en el Fuerte Grommash",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "Los Acechalagos y Oráculos Anca Vil están en la orilla del lago, al sur de {area:237}, al este de {area:228}.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Las espadañas y la hierba lanza crecen junto al agua en {object:172958}, al este de La Calle Mayor.",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "{object:1593} está en el embarcadero de la orilla del lago, al este de {area:228}.",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "{object:177790} está en la costa al oeste de {area:240}. Contiene {item:15882} para {quest:30}.",
		["Vile Fin murlocs"] = "Múrlocs Anca Vil",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{area:1338} shore"] = "Orilla de {area:1338}",
		["{area:233} comes later, on the southern loop"] = "{area:233} viene más tarde, en el circuito del sur",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de un {object:177785} del lago",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}: botín raro de los gnolls",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{npc:11798}, en {area:2361}, lleva allí a los druidas; luego sigue volando a {zone:1454} para el zepelín",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, en {area:2362}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: para Quinn, en el camino al norte al final",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} espera al noreste de la casa. Escóltalo de vuelta hasta {npc:1950}; los huargos atacan por el camino.",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}: {quest:516}, en el circuito del sur",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entrena a los paladines en {area:159}, a poca distancia al norte por el camino desde las torres de zepelín. Vuelve por el mismo camino para ir al Bosque de Argénteos.",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} y {npc:3347} llevan la tienda de alquimia de La Calle Mayor; {npc:11046} está al lado.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, dentro del Fuerte Grommash",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, una visita a los líderes de la Horda",
		["{object:1599}, just east of the keep"] = "{object:1599}, justo al este del castillo",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, en la siguiente guía",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Ayuda a {npc:261366}: quédate a su lado cuando {npc:261367} y los marinos de {area:21} suban la cresta",
		["Bael'dun fortress"] = "Fortaleza Bael'dun",
		["Bristleback camps"] = "Campamentos Lomopelo",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran está encadenado en el campamento de jabaespines al oeste del camino.",
		["Down the {area:458} to {area:378} again."] = "Baja otra vez por {area:458} hasta {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Llena el {item:7766} en el abrevadero de los jabaespines",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "Vuela a {area:1638} y entrena tus rangos de nivel 20: {npc:3033} está en {area:1639}.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Vuela a {area:1638} para entrenar: {npc:3033} está en {area:1639}.",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Follow the {area:458} south to {area:378}."] = "Sigue {area:458} hacia el sur hasta {area:378}.",
		["He gives you the {item:15826}"] = "Te da {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Después ofrece {quest:1838} (1838, nivel 30): requiere {area:1717} y te envía por todo Kalimdor y los Reinos del Este. La guía de clase de guerrero {quest:1838} la cubre.",
		["Keep it: the {object:107045} is beside {area:272}"] = "Guárdala: {object:107045} está junto a {area:272}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Guárdala: {npc:12696} en {zone:1440}, en la siguiente guía",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "Guárdala: {npc:5875} en {zone:1454}, al final de esta guía",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Al norte, a {area:383}. {npc:3682} acampa al pie de las colinas; {npc:261366}, el ermitaño de la cresta que hay detrás, solo tiene trabajo para ti cuando {npc:3682} te envía arriba.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "De vuelta por {area:458} hacia {area:378}: los Asaltantes Crines de Acero entre los campamentos Lomopelo, a ambos lados del camino al norte del campamento, llevan {item:277277}. Entrégalos a {npc:3432} en tu última parada en {area:380}.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Tauren: {npc:11957} espera en la colina sur, sobre el puente. Cielonato: {npc:272054} está al sur de los puentes gemelos. Después, las guaridas al este del lago: sal de tu forma, pulsa la estatua de la entrada para tener cinco minutos de sigilo, evita a los espíritus del interior y coge una reliquia de cada; {item:280680} está al pie de la estatua del gato blanco.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Los Sobrestantes y Déspotas de Ventura y Cía. de la mina en la esquina noreste de la zona sueltan la {item:5097}.",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "La máquina voladora de los enanos está en su plataforma dentro de la excavación.",
		["The flying machine"] = "La máquina voladora",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} es el cañón bajo {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} está en el borde norte de {area:382}, junto a la torre de Ventura y Cía. Contiene {item:15883} para {quest:30}.",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Los Desechanubes Truenalcón vuelan en círculos sobre las mismas llanuras al sur del campamento.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Los Truenabezas pastan en las llanuras justo al sur de {area:378}. {quest:884}, un lagarto del trueno azul, deambula entre ellos: su Punta de cola de Owatanka inicia una misión.",
		["Twitching Antennae"] = "Antenas temblorosas",
		["Twitching Antennae from the silithid"] = "Antenas temblorosas de los silítidos",
		["Venture Co. tower"] = "Torre de Ventura y Cía.",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}: Kodos de los Baldíos Perdidos en las llanuras alrededor del campamento Kolkar",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: usa una mitad en {area:2362}",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} de {npc:3490}; los herboristas la recogen en las llanuras",
		["{item:2449}: herbalists pick it here"] = "{item:2449}: los herboristas la recogen aquí",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798}, en {area:2361}, lleva volando allí a los druidas",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: la bienvenida de {npc:3033}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}: usa {item:15826} con ellas; recorren las llanuras alrededor de {area:380}",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, arriba en el árbol justo al este de {npc:3341}",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341} espera en un pequeño campamento más al sur, en el camino hacia {area:359}.",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389} está en el puesto de vigilancia frente a los Kolkar, justo al oeste de {area:380}.",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394} está en el campamento Kolkar al noroeste de {npc:3389}.",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395} camina entre los Kolkar de {area:388}, al sureste de {area:380}.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396} dirige a los Kolkar en la orilla oeste de {area:387}, al sur de {npc:3389}. Entrega su cabeza a {npc:3389} en tu última parada en {area:380}.",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}: los huevos están en {area:390}, más adelante",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en lo alto de la torre",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}. Guárdala: Kadrak en {area:1703}, en la siguiente guía",
		["{npc:3430}, in the cage"] = "{npc:3430}, en la jaula",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} ofrece {quest:95774} cuando entregas {quest:4921}",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, en el borde norte del campamento",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}, junto al maestro de jinetes del viento. Guárdala: {quest:1483} está en Sierra Espolón, más adelante",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} está encadenado dentro del bastión. Habla con él para empezar la escolta y no te alejes: los soldados de Theramore atacan a la salida. Te acompaña de vuelta a {area:392}.",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878} acampa junto al camino al este de {area:380}.",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}, justo al oeste de {npc:3341}",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} espera en la colina al sur de {area:392}, de camino al norte.",
		["{npc:5909}, a few steps away"] = "{npc:5909}, a unos pasos",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} está en {object:172961}, en el lado oeste de la ciudad.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} en {zone:1458}, dos guías más adelante",
		["{object:3972} poster"] = "Cartel de {object:3972}",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}: {npc:7233}, junto a {area:382}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Vuelve al camino hacia el sur. Donde gira al este hacia {area:287}, {npc:2214} espera en {area:285}.",
		["Back to {npc:8582}"] = "Vuelve con {npc:8582}",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Todos los nagas Colafuria de la playa al norte del puesto sueltan cabezas.",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Sigue el camino al norte hacia {area:467}. Los Antlered Coursers pastan por el camino; las Bestias de savia, los Corredores Crepusculares y los Dragones clarividentes recorren los bosques bajo el pico, y los druidas Cenarion ocupan la arboleda de allí.",
		["Follow the road west to {area:460}."] = "Sigue el camino al oeste hasta {area:460}.",
		["Gaea Dirt Mounds"] = "Túmulos de Gaia",
		["Gaea Seeds"] = "Semillas de Gaia",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "Sigue al norte por el camino. {npc:12862} espera en el campamento maderero Grito de Guerra, al sur del Puesto del Hachazo.",
		["Naga heads"] = "Cabezas de naga",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Al suroeste del Refugio Roca del Sol está {area:465}, quemada. Planta las Semillas de Gaia en los túmulos de tierra del fondo del valle; los elementales de fuego sueltan {item:16312}. Las arpías Furia Sangrienta y las emboscadoras anidan en el lado norte; las destripadoras y las plumabribonas, al sur.",
		["Sputtervalve in {area:392}: the next guide passes there"] = "Petardol en {area:392}: la próxima guía pasa por allí",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Guía el {npc:271181} de {npc:267214} fuera del barranco hasta el camino principal en menos de cuatro minutos; si se rompe la canalización, vuelve a hablar con {npc:267214}.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "El camino sube al norte como {area:1076}. {quest:1483} tiene una choza donde el camino se bifurca al este hacia {area:461}.",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864} patrulla el camino al este de {area:428} hacia {area:430}.",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "Usa {npc:212753} en {object:645153} como sacrificio voluntario y mata a {npc:212753} que responde. {quest:95883} es de élite: se recomienda ir en grupo.",
		["{area:431} is just north up the road."] = "{area:431} está justo al norte, siguiendo el camino.",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, de un {npc:1973}",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, de cualquier arpía Furia Sangrienta",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Piedrasoles relumbrantes de las arpías Furia Sangrienta",
		["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860}: Grish está en {area:1718}, en la próxima guía",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, junto a {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, arriba en la cornisa",
		["{npc:12736} at Zoram'gar, at 27"] = "{npc:12736} en Zoram'gar, a nivel 27",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia en {area:272}",
		["{npc:271181}, on the road"] = "{npc:271181}, en el camino",
		["{npc:4198}, outside the gate"] = "{npc:4198}, fuera de la puerta",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "Osos, trepamusgos y leones",
		["Drull's ball and chain"] = "La bola y cadena de Drull",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Llena {item:7768} en {object:107045} junto a la posada",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "Sigue el camino hacia el sur hasta la excavación enana de {area:359}. {npc:3421} se esconde en el borde sur de la excavación; {object:3646} está en el fondo.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "Desde {zone:1454} (zepelín desde las torres a las afueras de {zone:1458}), vuela a {area:378}.",
		["Keep it: the {area:287} coast, later on the route"] = "Guárdala: la costa de {area:287}, más adelante en la ruta",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj se esconde en la ladera sobre {area:290}, al sur del Castillo de Durnholde, de bajada hacia las flores.",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "Al suroeste del Castillo de Durnholde, {item:3502} crecen en las laderas sobre el río.",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "Toma el zepelín desde las torres a las afueras de {zone:1458} hasta {zone:1454} y entrena antes de seguir volando.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Las granjas al este del pueblo de {area:287}. {npc:232} trabaja el campo junto a la granja del norte y {npc:2403} el que está más al sureste; hay mozos de labranza y granjeros por todas partes. {npc:2451} cuida el campo al sur de las granjas.",
		["The smithy"] = "La herrería",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "La herrería está en medio del pueblo de {area:287}. {npc:2404} y sus aprendices trabajan en la forja; {object:1736} está apilado al lado. {npc:2449} pasea por la calle al norte.",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "El ayuntamiento está en el lado oeste de {area:287}. {npc:2335} (30) y {npc:2448} están dentro con el Registro de Trabalomas; la Proclamación de Trabalomas está colgada al lado. Los consejeros recorren el pueblo.",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288} está al sur del pueblo de {area:287}. Los mineros trabajan en los túneles; {npc:2305} (30) y {npc:2450} (29) están al fondo.",
		["Town hall"] = "Ayuntamiento",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Al oeste de Molino Tarren, osos grises, trepamusgos del bosque y leones monteses hambrientos recorren las colinas de bajada a las granjas. Los trepamusgos sueltan {item:3477} rara vez; solo necesitas uno.",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} es tu base en esta guía: la piedra de hogar te trae de vuelta aquí dos veces. Todos están alrededor de la plaza del pueblo.",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: los Campesinos de los campos",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, en el Apothecarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, en {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: órdenes para {npc:270438}, de camino al Castillo de Durnholde",
		["{npc:2238}'s ball and chain"] = "La bola y cadena de {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} es el perro de {npc:232}, en la granja del norte de {area:286}.",
		["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:2391}: Poisons"] = "{npc:2391}: Venenos",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}, junto a los muelles de {area:392}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "La choza de {npc:5899} está en la cresta sobre el abrevadero de los jabaespines, al sur de {area:378}, de camino a {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: el odre azul se llena en {zone:1440}, en la siguiente guía",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: el odre rojo de {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, un gran trillanodonte, nada en las aguas poco profundas de {area:391}, al este de {npc:3388}.",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Vuelve al sur al campamento y sube a {zone:1456} para volar a {area:378}.",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Vuelve al suroeste a {area:421}. Los Elementales de agua podrida flotan por sus orillas; el cenador está en la isla, frente a la avanzada de la Alianza.",
		["Back west to Zoram'gar before heading east for good."] = "Vuelve al oeste a Zoram'gar antes de ir al este definitivamente.",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Sube por el sendero hasta lo alto de {area:2097}. {npc:10646} está cautiva junto a {npc:10896} (29): acaba primero con los guardias y con {npc:10896}, luego libérala y protégela en la bajada; te atacarán emboscadores Tótem Siniestro por el camino.",
		["Felmusk satyrs"] = "Sátiros Putredores",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Sigue el cañón al este, sal de las mesetas y llega a El Desierto de Sal. Los goblins y gnomos de {area:2240} son neutrales y dan misiones a ambas facciones.",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Sigue el camino principal al este, pasado {area:415} (Alianza: no te salgas del camino). {npc:12678}, un gran oso pardo, recorre {area:418} al sur del camino, al oeste de {area:421}. Su zarpa inicia la siguiente misión de caza.",
		["Galak centaurs"] = "Centauros Galak",
		["Gazebo"] = "Cenador",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Muestras de toxina de altopenumbra, de los {npc:264096}",
		["His crate is for Stranglethorn, later on the route"] = "Su caja es para Tuercespina, más adelante en la ruta",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Sigue al este por el camino. {npc:12858} espera al suroeste del Aserradero Grito de Guerra. Él y sus gruñones asaltan {area:2360}: deja que ellos atraigan a los enemigos y quédate con {npc:12858} hasta que muera {npc:12860}.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Mata al {npc:10720} que viene a por {npc:10638}",
		["Naga brazier"] = "Brasero naga",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Al norte del campamento, las arañas invaden el cementerio de {area:17044}. Usa el {item:273015} de {npc:264074} en los {npc:264096}; las tejedoras sueltan {item:273181}. {npc:264082} está en el extremo norte: su {item:273658} inicia {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Al noroeste del Puesto del Hachazo, los sátiros Putredores acampan en el bosque. Cualquier sátiro puede soltar cuernos.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Baja en el elevador y sigue el camino al este por los cañones hasta {area:484}, un poblado tauren en lo alto de las mesetas. Su elevador está en el lado norte.",
		["Sapphires of Aku'Mai"] = "Zafiros de Aku'Mai",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "Al sur de la Cumbre de la Nube Negra, las arpías de {area:487}. {npc:4490} (31) camina entre ellas: reduce las arpías a su alrededor antes de atraerla. Las Arpías estridentes, Malaplumas estridentes y Clamavientos estridentes de allí son las de {npc:4877}.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Habla con {npc:3057}, en {area:1638}: {quest:93739}",
		["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "Baja de {zone:1456} en un elevador. El campamento del Anillo de la Tierra está al norte de las mesetas: {npc:264074}, {npc:264072} y {npc:259118}.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Baja en el elevador. El huevo está en un nido en el fondo del cañón, en uno de tres sitios: al sureste de las mesetas (52.3,55.2), al este (56.4,50.4) o al suroeste (37.6,56.1).",
		["The Earthen Ring"] = "El Anillo de la Tierra",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Los fúrbolgs Maderiza ocupan los bosques al este de {area:421}, al sur del camino. Coloca {item:16972} en {object:178206} y protégelo: los fúrbolgs vienen a derribarlo. {npc:12918} llega el último; su tótem cae en la cesta.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "Los campamentos Galak llenan el cañón al norte del Poblado Viento Libre; exploradores, vaqueros y cazavientos comparten todos los campamentos. Un {npc:10617} solitario va de un campamento a otro: mátalo cuando lo encuentres, su nota inicia una misión para {area:2237}.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Los zafiros son cristales azules en las paredes de los túneles que llevan al portal de {area:2797}, bajo tierra y fuera de la mazmorra: bucea desde el foso, por debajo del muro, hasta la cueva. Los sátiros y nagas de los túneles son élite: se recomienda ir en grupo. Los cristales reaparecen rápido, así que no hace falta adentrarse mucho.",
		["The Wanted poster beside {npc:10537}"] = "El cartel de Se busca junto a {npc:10537}",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "La fuente está en medio de {area:418}: usa allí {item:7767}.",
		["The next guide flies on from here to {zone:1454}."] = "La siguiente guía sigue volando desde aquí hasta {zone:1454}.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "El camino a los zafiros pasa por las ruinas sumergidas del extremo norte de la playa: baja las escaleras hasta el foso.",
		["Thistlefur Hold"] = "Bastión Piel de Cardo",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Al oeste del Poblado Viento Libre, los campamentos Tótem Siniestro bajo {area:2097}. Las Notas secretas están en Cofres de documentos en los campamentos del sureste, suroeste y noroeste.",
		["for {npc:5901}, south of {area:392}: next guide"] = "para {npc:5901}, al sur de {area:392}: siguiente guía",
		["{area:2797} ruins"] = "Ruinas de {area:2797}",
		["{area:418} fountain"] = "Fuente de {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, de {npc:264081}",
		["{item:273658}, from {npc:264082}"] = "{item:273658}, de {npc:264082}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, junto al maestro de jinetes del viento",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "La siguiente misión de {npc:10428}, El fuego Sagrado, termina en {zone:1456}, fuera de esta ruta. Omítela.",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}, una gran sable de la noche, merodea por los bosques al sureste del Aserradero Grito de Guerra. Su garra inicia la siguiente misión de caza.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, una pantera de las sombras, acecha en los bosques alrededor de {area:426}, al oeste del campamento Putredor. Su cabeza inicia la siguiente misión de caza.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717} camina al norte por la playa hasta un brasero naga. Apaga el brasero y protégelo durante las oleadas de nagas hasta que muera Vorsha la Azotadora.",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}: su escolta empieza enseguida",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: solo si llevas las páginas del manual",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} te ofrece después una misión de {area:2797}; déjala salvo que tengas grupo.",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}, un elemental de agua corrupto, flota en {area:421}. Su {item:16408} inicia una misión para el Puesto del Hachazo.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, un añadido de Forever, está en la orilla oeste de {area:421} con tres misiones rápidas de cazadragones.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} está en lo alto de una meseta al este de los campamentos Galak. Para {quest:1149}, salta desde el final de los tablones a su lado: aterrizarás sano y salvo.",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}: su carta es para Martek el Exiliado, en {zone:1418}, hacia el nivel 38",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}, un elemental de roca que pega fuerte, recorre los acantilados de {area:482}. {npc:4499} es élite: se recomienda ir en grupo.",
		["{object:176344}, north-west camp"] = "{object:176344}, campamento del noroeste",
		["{object:176344}, south-east camp"] = "{object:176344}, campamento del sureste",
		["{object:176344}, south-west camp"] = "{object:176344}, campamento del suroeste",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
