t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Draenethyst crystals"] = "Cristales de draenetista",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Sigue la costa hacia el sur. Los exploradores naga vadean la orilla y llevan los fardos de juncos; {object:759} burbujea en las colinas justo al este.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Dale los colmillos a Unbagwa y quédate a su lado: llama a tres oleadas de gorilas y luego a {npc:1514}. Lucha contra ellos de uno en uno.",
		["His strongbox waits at his old camp north of {area:75}."] = "Su caja fuerte espera en su antiguo campamento al norte de {area:75}.",
		["Jungle stalkers"] = "Acechadores de la selva",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Sal del pueblo por el túnel; la nota está en la cala pirata justo al norte de {area:35}.",
		["Mistvale gorillas"] = "Gorilas de Velo de Bruma",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru el Garrote deambula por el claro al suroeste de {area:76}; su garrote inicia una misión.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Al noreste de Velo de Bruma, los seguidores de Zanzil acampan en la jungla; cualquiera de ellos puede llevar la mezcla.",
		["Pirate ghosts"] = "Fantasmas piratas",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "Vuelve al este pasando {area:75} y sigue el camino al sureste hasta el pequeño puesto de la Horda en la orilla.",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Cabalga al noreste hasta {area:76}. Los cristales están a lo largo de la subida hasta la jaula de {npc:5391}.",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "Cabalga al oeste por el camino hasta el campamento draenei de {area:657}, cerca de la entrada desde {zone:1430}.",
		["Sawtooth crocolisks"] = "Crocoliscos Denteserra",
		["Skullsplitter warriors"] = "Guerreros Machacacráneos",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "Toma el camino al norte desde {area:35}; Unbagwa está sentado en una colina en {area:1737}, al este del camino.",
		["The Bloodsail ships"] = "Los barcos Velasangre",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "El barco llega al puerto de {area:35}. Los que dan misiones están en las pasarelas alrededor del puerto y en la posada.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Los gorilas deambulan por el valle alrededor de Unbagwa. Los ancianos sueltan las tripas; cualquiera puede soltar un colmillo.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Los acechadores de la selva cazan en la jungla al sur de {object:3202}, hacia la costa oeste.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Los tres piratas fantasmales rondan la jungla al norte de {area:35}, cerca de los campamentos de Zanzil: {npc:2535} y {npc:2536} están juntos, {npc:2537} más al este.",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "Los tres barcos están frente a {area:43}. Las tripulaciones son de nivel 42-45, Aguasmansas 45, Sinquilla 46 y {npc:2546} 48: a nivel 41 es un combate para grupo o para el final de la guía. Si vas, nada hasta ellos y atrae a la tripulación a la borda de uno en uno. Un pergamino, {quest:624}, está en la cubierta de los barcos: cógelo.",
		["Venture Co. mine"] = "Mina de Ventura y Cía.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "Al oeste de la expedición, los jefes Cabellesangre {npc:1061} y {npc:1062} están juntos en las Ruinas de Zul'Kunda. Limpia antes a sus guardias y luego atráelos.",
		["Zanzil's camps"] = "Campamentos de Zanzil",
		["Zul'Kunda"] = "Zul'Kunda",
		["Zul'Mamwe"] = "Zul'Mamwe",
		["the {object:2076}"] = "{object:2076}",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} está preso en {area:76}, al noreste del pantano. Libéralo y síguelo, defendiéndolo de las criaturas del pantano que lo persiguen.",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {area:484}"] = "Vuela a {area:484}",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Grimtotem camp"] = "Campamento Tótem Siniestro",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Sigue cabalgando hacia el oeste hasta la costa. Los Videnistas y Quebradores Reptacostas de las playas sueltan la baliza de socorro de OOX-22/FE aproximadamente una de cada cuarenta muertes: si cae, úsala para empezar la misión.",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos: {npc:3685}, junto a {npc:3690}, en {area:222}.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Al norte de los gnolls, los ogros ocupan un puesto en lo alto de una colina; atrae hacia ti a los magos ogros. El cobalto está en los montículos de tierra alrededor del puesto, y el pergamino está en el suelo, dentro.",
		["Ride north-east to the goblin harbour on the coast."] = "Cabalga hacia el noreste hasta Puerto Bonvapor, el puerto goblin de la costa.",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Cabalga hacia el suroeste hasta las ruinas de ogros bajo {area:1105}. Están llenas de chamanes, brujos y destructores; los Señores de la Magia del extremo sur llevan el orbe.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Caballos esqueléticos: {npc:4731}, junto a {npc:4773}, en {area:159}.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Los tauren Tótem Siniestro acampan junto a la arboleda de los duendes dardo; asaltantes, naturalistas y chamanes llevan cuernos.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "La colmena Zukk'ash excava en las colinas al sureste del campamento; {quest:7731} espera en su cámara más profunda.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "El mapa de batalla está en el campamento Zarpaleña al sur de Mojache.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Lobos: {npc:3362}, junto a {npc:4752}.",
		["Woodpaw battle map"] = "Mapa de batalla Zarpaleña",
		["Woodpaw north camp"] = "Campamento Zarpaleña del norte",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["for the {zone:1425}, around level 48"] = "para {zone:1425}, hacia el nivel 48",
		["for {zone:1454}, around level 45"] = "para {zone:1454}, hacia el nivel 45",
		["water pouches in your bags"] = "bolsas de agua en tus bolsas",
		["{area:392} for the Felsteed"] = "{area:392}, por el Corcel vil",
		["{npc:3690}, riding trainer"] = "{npc:3690}, instructor de equitación",
		["{npc:4752}, riding trainer"] = "{npc:4752}, instructor de equitación",
		["{npc:4773}, riding trainer"] = "{npc:4773}, instructora de equitación",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: para {zone:1454}, hacia el nivel 45",
		["{quest:2863}: one hour from now"] = "{quest:2863}: dentro de una hora",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Cuevas de dragones",
		["Forest walkers"] = "Caminabosques",
		["Frayfeather hippogryphs"] = "Hipogrifos Plumavieja",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "Al noroeste por el camino, los Yetis Estigmodio viven alrededor de las cuevas de las colinas. Cualquiera puede soltar también una {quest:7738}, que inicia su propia misión.",
		["Onyxia's eggs"] = "Huevos de Onyxia",
		["Rage Scar yetis"] = "Yetis Estigmodio",
		["Ride back north to Brackenwall."] = "Vuelve cabalgando al norte, a Murohelecho.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Cabalga hacia el noroeste hasta {area:1108}; {npc:14637} espera en el muelle.",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Cabalga hacia el suroeste hasta {object:2555} y luego al este por {area:511}. Los Exploradores y Ceniazotes Pirocabello recorren su borde norte con las Proles y Crías abrasadoras; los Horrocrustos guardan las cuevas de dragones más al sureste. El rapé, el grog y la caja fuerte de Mok'Morokk están en los campamentos de los dragonantes.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Cabalga hacia el oeste por el camino; el pergamino está a la orilla del agua, en el extremo oeste del pantano.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Elementales marinos y Rocíos del mar recorren la orilla alrededor del muelle. Dispara primero a los gigantes con {item:18904}: encogidos, pierden su fuerza de élite. Los Zancacostas vadean en el agua; los Caminantes de la tierra y los Gigantes del risco recorren las colinas más al norte.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Al sur del valle, los Hipogrifos Plumavieja anidan en las laderas; casi todos sueltan tendones y fragmentos metálicos.",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "Al suroeste, los yetis tienen su guarida en {area:1105}; cualquier yeti de allí puede soltar una piel gruesa.",
		["Sprite darters and forest walkers"] = "Duendes dardo y Caminabosques",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Los Huevos de Onyxia están en las cuevas de dragones del sureste de {area:511}, guardados por los Horrocrustos; destroza cinco.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Los duendes dardo revolotean sobre la arboleda justo al oeste del campamento y llevan los {item:9589}; los Caminabosques deambulantes, un poco más al oeste, llevan los Troncos astillados.",
		["The {area:511}"] = "{area:511}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "para {npc:5598} en {zone:1425}, hacia el nivel 48",
		["for the {zone:1425} owlbeasts, around level 48"] = "para las lechubestias de {zone:1425}, hacia el nivel 48",
		["the {object:2555}"] = "{object:2555}",
		["{quest:7738}, a rare drop"] = "{quest:7738}, botín raro",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Su siguiente encargo pide el {item:10552} de fieles élite: déjalo.",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "Kalaran Espada del Viento está solo al sur de {area:1446}, al borde de La Caldera. Escucha su historia.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Solo con la {item:11818}: vuelve al este hasta el {object:173265} de la excavación.",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "Vuelve al norte hasta {area:1446}. Quédate aquí: la siguiente guía empieza con el vuelo a {area:75}.",
		["Scrimshank's gear"] = "Equipo de análisis de Patagolpe",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "Al sur de {area:982}, los ogros Machacaduna ocupan su base, con {npc:12046} en el extremo este. Desentierra adornos de {quest:3161} entre combate y combate.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Ve al oeste por el camino del sur; {npc:7771} acampa junto a las ruinas de {area:1938}. Ponte su {item:9978}: muestra los adornos enterrados, aquí y alrededor de {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Al oeste de Gadgetzan, usa la {item:8584} junto a la charca del campamento trol.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "el {item:8526} crece en {zone:1425}, hacia el nivel 48",
		["the {object:173265}"] = "el {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, botín poco común",
		["{item:8623}, a rare drop"] = "{item:8623}, botín poco común",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} espera en el valle. Acompáñalo hasta su esposa, {npc:6015}, en {area:977}, al noreste cruzando el desierto: no te alejes, ve despacio para que te siga y defiéndelo de lo que le ataque. No montes ni uses la piedra de hogar lejos de él. {npc:8579} también está en el puerto.",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Vuelve al oeste a {area:350}; los forestales y tiradores están cerca del refugio, y los exploradores y avanzadas, en las laderas al sur.",
		["East of the village, the violet flower grows in the hills."] = "Al este del poblado, la flor violeta crece en las colinas.",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Fly to {area:75}"] = "Vuela a {area:75}",
		["Highvale"] = "Vallealto",
		["His next request, going on to the {area:355}, is for a group."] = "Su siguiente encargo, que continúa en {area:355}, es para grupo.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "La calavera del cazador Malkhor está en un montón bajo las ruinas Vilrama, y sus huesos, en otro montón al pie de {area:354}. Las vasijas de sangre contaminada están en las terrazas inferiores, y {npc:14757} está preso en la cima. No te salgas de los senderos: los trols de dentro son élite.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Al norte por la costa, la cesta de merienda de {npc:14731} está en el islote; la vigila un {npc:14748}.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Ve hasta el extremo oeste, a {area:348}, la ciudad de los Martillo Salvaje, y deja el mensaje junto al pozo del centro. La ciudad está llena de guardias de la Alianza: entra, déjalo y sal.",
		["Ride back north to the bloodmages."] = "Vuelve al norte con los magos sangrientos.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Sal de {area:75} hacia el oeste y ve al sur por el cañón hasta {zone:1419}; los dos magos sangrientos están junto al camino, nada más entrar.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Al sur del refugio, los trols Secacorteza ocupan sus poblados. Todos llevan un cráneo: con veinte, usa {item:15002} para hacer el Pico cargado de Nimboya y clávalo dentro del poblado.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "De nuevo al suroeste, el exiliado se esconde junto a las ruinas de {area:353}.",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Las tortugas grandes se arrastran por las playas al norte del poblado. Las botellas de oporto de {npc:2491} también están en estas playas, pero su misión no forma parte de esta ruta. Un quijaforte puede soltar, rara vez, la baliza de socorro de OOX-09/HL: guárdala.",
		["The bloodmages"] = "Los magos sangrientos",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Las cajas de {item:8684} están alrededor del campamento abandonado de la Horda en {area:351}, entre los mocos.",
		["The next guide starts here, at {area:3317}."] = "La siguiente guía empieza aquí, en {area:3317}.",
		["The secret lies on the {area:307}, above the beach."] = "El secreto está en {area:307}, sobre la playa.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Sus misiones siguientes piden otra vez las mismas partes a cambio de un objeto de mejora y no dan experiencia: déjalas.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "para {npc:6986} en {zone:1454}, hacia el nivel 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "para {npc:7825} en {zone:1458}, hacia el nivel 50",
		["{area:348} well"] = "Pozo de {area:348}",
		["{item:8704}, a rare drop"] = "{item:8704}, botín poco común",
		["{npc:14731}'s lunch"] = "El almuerzo de {npc:14731}",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, en la cima de {area:354}",
		["{npc:7801}'s camp"] = "Campamento de {npc:7801}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Vuelve al noreste con {npc:8420}.",
		["Back to {area:1099}"] = "De vuelta a {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Vuelve con {npc:11548} al santuario; mantente al oeste de los guardias de {area:3137}.",
		["Back to {object:3202}"] = "De vuelta a {object:3202}",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "Sigue al sur hasta {area:35}. {npc:7406} tiene su taller en el anillo superior de la bahía.",
		["Follow the road north to {area:1237}, the Horde camp."] = "Sigue el camino hacia el norte hasta {area:1237}, el campamento de la Horda.",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Sigue el camino hacia el sur; los basiliscos toman el sol en las rocas al este, en medio de la selva. Sus fragmentos caen a menudo.",
		["Frayfeather Hippogryphs"] = "Hipogrifos Plumavieja",
		["Ironjaw Basilisks"] = "Basiliscos Quijahierro",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Guarda las entregas para {npc:4046}, {npc:8659} y {npc:6522}: pasarás por {zone:1456}, {zone:1454} y {zone:1458} más adelante.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "Guarda el pago de {npc:8659} y {quest:3504} de Ag'tor Puñosangre: se entregan en {area:1237} en una visita posterior.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Guarda {quest:3444}: el cofre de {npc:7771} se abre en una visita posterior.",
		["Only once all three robots are home"] = "Solo cuando los tres robots estén en casa",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Cabalga hacia el este por el camino desde el Puesto del Hachazo. {npc:11548} espera en {area:1235}, junto al camino, a pocos pasos al oeste de {area:3137}, de la Alianza: llega desde el oeste y evita a los Centinelas de Azshara y a Jarrodenus (élite).",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "Cabalga al noreste hasta el campamento del goblin en los acantilados sobre {area:1227}.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Cabalga al suroeste hasta las ruinas. Las cuatro tablillas están entre las ruinas, custodiadas por nagas Látigo de Ira; cualquier sirena o mirmidón Látigo de Ira puede llevar la runa de {npc:8420}.",
		["Ride west back to {area:1237}."] = "Cabalga de vuelta al oeste, a {area:1237}.",
		["Sprite Darters"] = "Duendes dardo",
		["Take the zeppelin back to {zone:1454}."] = "Toma el zepelín de vuelta a {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Las apariciones de Altonato rondan las ruinas justo al norte del santuario; los sátiros Haldarr acampan un poco más al norte.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "Los hipogrifos tronadores vuelan sobre las colinas justo al sur de {area:1237}.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "El campamento de los elfos de sangre está justo al sur de {npc:8420}. Sus cuatro piezas de equipo están en las cajas alrededor del campamento.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Los dragones feéricos revolotean por el bosque justo al oeste del campamento. Usa la vasija sobre cada uno que mates.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Los hipogrifos anidan en las colinas al suroeste del campamento. Mata uno y usa la Vasija de muisek hipogrifo sobre su cuerpo.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Los antárboles deambulan por los caminos del bosque entre el campamento y el centro de {zone:1444}; hay pocos, así que búscalos por los senderos.",
		["The {object:2076} beside {npc:2519}"] = "{object:2076} junto a {npc:2519}",
		["To {object:3202}"] = "A {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumas de hipogrifo sin estropear",
		["Wandering Forest Walkers"] = "Caminabosques deambulantes",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "La torre del Archimago Xylem está en el acantilado justo al norte de {area:1237}; el sendero sube serpenteando por su lado norte.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, La Calle Mayor",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "El alquitrán de {npc:7876} y las muestras del Alquimista Morterozugg vienen de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, en el borde este del campamento: no da experiencia, solo un teletransporte a la torre de Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} se reúne en la siguiente guía; el pago de {npc:4046} se entrega a {npc:8587} más adelante.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "Vuelve al noreste, a {area:251}.",
		["Back to {area:2268}"] = "Vuelve a {area:2268}",
		["Bridge into {area:254}"] = "Puente hacia {area:254}",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Cruza el sur del cráter hasta el pilón de los acantilados occidentales.",
		["Eastern Pylon"] = "Pilón del este",
		["Fly to {area:340}"] = "Vuela a {area:340}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Sigue los acantilados hacia el sur hasta {quest:3821}, la colina de los ogros Pirontraña. Los restos de {npc:9136} están al pie.",
		["Free Darrowshire Spirits: talk to them"] = "Libera Espíritus de Villa Darrow: habla con ellos",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "A partir de aquí recoge cada Cristal de poder (azul, verde, rojo, amarillo) y cada montón de {quest:3761} que encuentres: 25 de tierra en total, 20 para Hamuul y 5 para Morterozugg.",
		["Into the {zone:1427}"] = "Hacia {zone:1427}",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Guarda la carta de {npc:10267}: {quest:4808} está en {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Guarda {quest:4147}, de {npc:9118}, y la carta de {npc:8737} para guías posteriores.",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "Guarda {quest:5152}: Marlene vive en {area:197}, en {zone:1422}.",
		["Lar'korwi Mates"] = "Amigos de Lar'korwi",
		["North of Torwa, a dead Threshadon lies by the water."] = "Al norte de Torwa yace un trillanodonte muerto junto al agua.",
		["Northern Pylon"] = "Pilón del norte",
		["Out of the refuge"] = "Fuera del refugio",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "La siguiente misión de Morterozugg requiere a la {npc:10041}, un jefe élite. Omítela.",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Baja por el lado este del cráter hasta el pilón de los acantilados orientales.",
		["Ride north back to {area:541}."] = "Vuelve al norte, a {area:541}.",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "Vuelve al sur hasta el camino y síguelo hacia el este cruzando toda la zona hasta {area:2268}.",
		["Stegodons and ravasaurs"] = "Stegodons y ravasaurios",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Coge una {object:176092} del cajón junto a Derrington para {quest:5096}, que harás a la vuelta. Equípate {quest:5401}: las Piedras de la Plaga solo caen mientras lo llevas puesto.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Toma el paso del lado oeste de {area:340} hacia {zone:1427}; después cabalga hacia el sur cruzando la garganta hasta el largo puente que entra en {area:254}. Dentro, baja por las pasarelas de cadenas y sal por la salida sur; no tomes los caminos a los portales de las mazmorras.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Los Amigos de Lar'korwi merodean por la jungla al noroeste de {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La cabeza de la muñeca y sus dos mitades están en las casas alrededor de {npc:10926}; únelas desde tus bolsas.",
		["The expedition's lost equipment lies in the south-west jungle."] = "El equipo perdido de la expedición está en la jungla del suroeste.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "La montaña te deja salir junto a {area:252}, lleno de orcos de nivel 55-57. Sigue el camino hacia el este por los acantilados del norte hasta el campamento de la Horda en {area:251}.",
		["The next guide starts here, at the chapel's flight master."] = "La siguiente guía empieza aquí, en el maestro de vuelo de la capilla.",
		["The pylon stands on the slope east of the refuge."] = "El pilón está en la ladera al este del refugio.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "La balsa está en la orilla del lago del sureste; la mochila pequeña está en el agua, a su lado.",
		["Use the Mangled Journal to start it"] = "Usa Un diario destrozado para empezarla",
		["Western Pylon"] = "Pilón del oeste",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "Con la misión de {npc:11063} en tu registro, la Plaga que matas a veces deja un {npc:11064}; habla con él para liberarlo. Mata no-muertos de camino al suroeste, hacia {area:2262}.",
		["{item:11116}, a rare drop"] = "{item:11116}, botín raro",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, junto al maestro de murciélagos",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "El fantasma de {npc:10926} está en las ruinas de {area:2262}, en el suroeste.",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, El Apothecarium: los viales se llenan más tarde en {zone:1447}",
		["{npc:9618}, just outside"] = "{npc:9618}, justo fuera",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} acampa en la esquina sureste del cráter.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, en la entrada",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} recorre las cuevas y túneles de mina de {quest:3821}; si no está, limpia los ogros de las entradas hasta que vuelva.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "De vuelta al norte a {area:1763}. Llena la cantimplora de {npc:10922} en la poza de la luna corrupta en el centro del campamento sur.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Las atalayas de Derrington, el caldero de Vandis y el barril de {npc:11615} se hacen en una visita posterior: guárdalas.",
		["Diseased Wolves"] = "Lobos malsanos",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Al este de Puesto del Veneno, el valle lleno de cráteres donde deambulan Bestias entrópicas y Horrores. Mata dos de cada y luego camina hasta cada uno de los tres cráteres de agua vil.",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "Sigue el camino al noreste hasta {area:1767}. Los Arrancamusgos Combadera y Machacadores Combadera del lado este del bosque llevan cada uno un {item:11503}; Griseznos Zarpira y Devastadores Zarpayel deambulan por el mismo bosque, para Talo.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Sigue el camino al noroeste. El sur de {area:1763}, alrededor de su poza de la luna corrupta, está en manos de cultores, adeptos, guardias y canes del Consejo de las Sombras.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Acampa junto a {area:202}, al sureste de {area:200}.",
		["Jadefire moonwell"] = "Poza de la luna Fuego de Jade",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Guarda la rama: {npc:5770} está en {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Guarda {quest:5158}: {npc:5901} está en {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Guarda {quest:8465} para {zone:1452}.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "Caballeros y magos trabajan en {area:192}; los médicos y cazadores acampan al sur.",
		["Northern crater"] = "Cráter norte",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "Solo si cayó una {item:13140}: úsala para iniciar la misión, luego libera a {npc:11018} de su jaula en {area:1770}, la cueva al norte de {area:1763}, y escóltala fuera.",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "Solo si rescataste a {npc:11018}: la súcubo {npc:9518} espera en el centro de {area:1763}, junto a {npc:11020}.",
		["Only with 5 Deadwood Headdress Feathers"] = "Solo con 5 Plumas de penacho Muertobosque",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Vuelve al sur pasando {area:1763} hasta la poza de la luna corrupta de los sátiros Fuego de Jade y llena allí el frasco de {npc:9996}.",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "Cabalga al norte por las colinas del este; {npc:1855} vive en una casita junto a {area:2619}, en la frontera con {zone:1423}.",
		["Ride north up the road again."] = "Vuelve a cabalgar al norte por el camino.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Cabalga al noroeste hasta las Ruinas de Andorhal. {npc:10667} espera en la posada en ruinas del lado oeste del pueblo; los esqueletos son de nivel 54-57, así que ve por los bordes.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Cabalga al suroeste pasando la granja de Piedramácula y sigue el camino al oeste de vuelta a {area:152}.",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "Cabalga al oeste hasta {area:192}; {npc:11610} se esconde en la colina al noreste.",
		["Ror stands at the far south end of {area:1761}."] = "El Señor Supremo Ror está en el extremo sur de {area:1761}.",
		["Scarlet Crusade"] = "Cruzada Escarlata",
		["Southern crater"] = "Cráter sur",
		["Southern {area:1763}"] = "Sur de {area:1763}",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Lleva el gatito a la misma poza de la luna y suéltalo allí; cuando se haya convertido en un {npc:10042}, llévalo de vuelta a {npc:9996} y haz clic en él para entregarlo.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Los Anales están entre los Libros enmohecidos del ayuntamiento de Andorhal; ábrelos hasta dar con el correcto.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "El poblado de fúrbolgs Muertobosque justo al oeste del túnel. {npc:9462} (56) está entre ellos. {npc:11557}, un fúrbolg amistoso, está sentado en el extremo norte del poblado.",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "El poblado de los fúrbolgs Muertobosque está justo al sur del Santuario. Cada Muertobosque que mates también sube tu reputación con {area:1769}; guarda las plumas de penacho.",
		["The Horde camp just north of {area:1763}."] = "El campamento de la Horda justo al norte de {area:1763}.",
		["The Jadefire moonwell"] = "La poza de la luna Fuego de Jade",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "El diario está en la granja, el armario dentro y la letrina detrás. Un {npc:10816} lleva la llave de la letrina; {npc:10836} aparece al abrir la letrina y lleva la llave del armario.",
		["The druids' camp is just past the border."] = "El campamento de los druidas está justo pasada la frontera.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "El camino acaba en {npc:15395}, fuera del túnel de {area:1769}, en el extremo noreste.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "Los lobos deambulan por los campos entre Andorhal, {area:200} y {area:202}. Termínalos en el camino de vuelta al este.",
		["The {area:1763} moonwell"] = "La poza de la luna de {area:1763}",
		["Western crater"] = "Cráter oeste",
		["{area:200} farmhouse"] = "Granja de {area:200}",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: las lechubestias están en {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, en el extremo sur del cementerio",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, en el borde sur del campamento",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "Las cacerías de {npc:1855} están en {zone:1423}: guárdalas para más tarde.",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, justo al oeste del campamento",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, en el lado oeste del Santuario",
		["{npc:9996}'s kitten"] = "El gatito de {npc:9996}",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210} es para {area:2268}: guárdala para más tarde.",
		["{quest:8470}, a rare drop"] = "{quest:8470}, un botín raro",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Gregor's and Harlo's quests lead to other zones: keep them."] = "Las misiones de Gregor y Harlo llevan a otras zonas: guárdalas.",
		["Ice Thistle yetis"] = "Yetis Cardo Nevado",
		["In the {object:172958}."] = "En {object:172958}.",
		["In the {object:172961}."] = "En {object:172961}.",
		["Linken's letter"] = "La carta de Linken",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Las matriarcas y patriarcas pegan fuerte: atráelos de uno en uno.",
		["Pristine Yeti Horns"] = "Cuernos de yeti prístinos",
		["Raging Owlbeasts"] = "Lechubestias enfurecidas",
		["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "Cabalga al oeste por el camino pasando {area:2251}; las Lechubestias enfurecidas deambulan por las colinas al norte.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "El poblado fúrbolg llena el valle al noreste de {area:2255}. Mata primero a los chamanes; curan. {npc:10738}, en la cueva del fondo, es élite: no entres.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Las colinas de los yetis empiezan justo al sureste de {area:2255}. Todos los yetis sueltan pelaje; solo las matriarcas y patriarcas sueltan cuernos, así que déjalos para después de la entrega.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "La tercera broma de Umi va contra goblins de {area:976} y Un'Goro: guárdala para más tarde.",
		["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255} es el pueblo goblin del lado este del valle.",
		["{item:12771}, a rare drop from the Winterfall furbolgs"] = "{item:12771}, botín raro de los fúrbolgs Nevada",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} en {area:1639}; {npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "{npc:7775}, un enano, acampa en {area:1137}, al noroeste de {area:1099}; tiene el elixir.",
		["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298} acampa entre las pozas humeantes de {area:2246}, al oeste del valle.",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} espera en {zone:1450}: guárdala para más tarde.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} la da {npc:7775} en {zone:1444}, más adelante en esta guía.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se entrega en el {object:176091} de {zone:1448}, en un viaje posterior.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, botín raro de los fúrbolgs Nevada",
} end)()
